from pathlib import Path
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4, landscape
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_CENTER
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak

out=Path('output/pdf/E4_Weight_Configurations_Completion_Rules.pdf')
navy=colors.HexColor('#132E57');blue=colors.HexColor('#3568BF');muted=colors.HexColor('#596E8F');line=colors.HexColor('#CCD9EE')
green=colors.HexColor('#2F6E46');greenbg=colors.HexColor('#E7F5EB');amber=colors.HexColor('#8A6411');amberbg=colors.HexColor('#FFF5D8');red=colors.HexColor('#9B2C2C');redbg=colors.HexColor('#FCECEC');grey=colors.HexColor('#657186');greybg=colors.HexColor('#EDF1F6')
s=getSampleStyleSheet();s.add(ParagraphStyle(name='TX',parent=s['Title'],fontName='Helvetica-Bold',fontSize=20,leading=24,textColor=navy,spaceAfter=5));s.add(ParagraphStyle(name='SubX',parent=s['Normal'],fontSize=9,leading=13,textColor=muted));s.add(ParagraphStyle(name='H2X',parent=s['Heading2'],fontName='Helvetica-Bold',fontSize=12,leading=15,textColor=navy,spaceBefore=10,spaceAfter=6));s.add(ParagraphStyle(name='Cell',parent=s['Normal'],fontSize=8,leading=11,textColor=navy));s.add(ParagraphStyle(name='CellC',parent=s['Cell'],alignment=TA_CENTER));s.add(ParagraphStyle(name='Head',parent=s['Cell'],fontName='Helvetica-Bold',textColor=colors.white,alignment=TA_CENTER));P=lambda x,st='Cell':Paragraph(x,s[st])
def footer(c,d):
 c.saveState();c.setFillColor(blue);c.rect(0,A4[0]-12,A4[1],12,fill=1,stroke=0);c.setFillColor(muted);c.setFont('Helvetica',7);c.drawRightString(A4[1]-28,18,f'AHM565 E4 Weight Configurations Completion Rules  |  Page {d.page}');c.restoreState()
def table(data,widths,rag=False):
 t=Table(data,colWidths=widths,repeatRows=1);cmd=[('BACKGROUND',(0,0),(-1,0),navy),('GRID',(0,0),(-1,-1),.5,line),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),8),('RIGHTPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6),('ROWBACKGROUNDS',(1,1),(-1,-1),[colors.white,colors.HexColor('#F7F9FC')])]
 if rag:cmd += [('BACKGROUND',(0,1),(0,1),greenbg),('TEXTCOLOR',(0,1),(0,1),green),('BACKGROUND',(0,2),(0,2),amberbg),('TEXTCOLOR',(0,2),(0,2),amber),('BACKGROUND',(0,3),(0,3),redbg),('TEXTCOLOR',(0,3),(0,3),red),('BACKGROUND',(0,4),(0,4),greybg),('TEXTCOLOR',(0,4),(0,4),grey)]
 t.setStyle(TableStyle(cmd));return t

doc=SimpleDocTemplate(str(out),pagesize=landscape(A4),rightMargin=28,leftMargin=28,topMargin=30,bottomMargin=28)
story=[P('E4. WEIGHT CONFIGURATIONS','TX'),P('Configuration Completion Rule Matrix  |  AHM565 Sheet E4','SubX'),Spacer(1,10),P('Configuration model','H2X'),P('E4 is split into two selectable sections. The primary Weight Configuration row links one Crew Code, Pantry Code, optional Potable Water Code and one optional Service Weight Adjustment. A second section holds any further Service Weight Adjustment items. This replaces the repeated fixed columns on the source sheet with a scalable relationship.'),Spacer(1,10)]
rag=[[P('STATUS','Head'),P('WEIGHT CONFIGURATION CODES','Head'),P('ADDITIONAL SERVICE WEIGHT ADJUSTMENTS','Head'),P('PAGE RESULT','Head')],[P('CONFIGURED','CellC'),P('Active and at least one complete primary row exists.'),P('Inactive, or active with at least one complete additional item.'),P('Every active section is CONFIGURED.')],[P('PARTIALLY CONFIGURED','CellC'),P('Some saved primary data exists but at least one required relationship is missing or invalid.'),P('The additional section is active and has incomplete data, or one active section remains incomplete.'),P('There is valid E4 progress, but not every active section is complete.')],[P('INCOMPLETE','CellC'),P('Active with no complete primary row, or applicability has not been reviewed.'),P('Active with no complete additional item.'),P('No active section has complete data.')],[P('SKIPPED','CellC'),P('Applicability reviewed and Weight Configuration Codes is not active.'),P('The section is not selected, or the main section is inactive.'),P('E4 is SKIPPED when the main section is explicitly not active.')]]
story += [table(rag,[130,240,250,165],True),Spacer(1,12),P('Section activation','H2X')]
activation=[[P('CONTROL','Head'),P('RULE','Head')],[P('Weight Configuration Codes'),P('Selectable by checkbox. When checked, at least one complete row is required.')],[P('Additional Service Weight Adjustments'),P('Selectable by checkbox only while the main section is active. When checked, at least one complete additional item is required.')],[P('Applicability review'),P('A saved checkbox decision is required before the page can leave INCOMPLETE status.')]]
story += [table(activation,[210,575]),PageBreak(),P('E4. WEIGHT CONFIGURATIONS - Data Rules','TX'),P('Source relationships and validation','SubX'),Spacer(1,10),P('Primary Weight Configuration row','H2X')]
primary=[[P('COLUMN','Head'),P('SOURCE / RELATIONSHIP','Head'),P('VALIDATION','Head')],[P('Weight Configuration Code'),P('User entry in Aircraft_Weight_Configuration_Codes.'),P('Required; one to three letters or numbers; unique for the aircraft.')],[P('Crew'),P('Aircraft_Crew_Code_Definitions / E2 Crew Codes.'),P('Required; must reference a saved E2 Crew Code.')],[P('Pantry'),P('Aircraft_Pantry_Codes / E2 Pantry Codes.'),P('Required; must reference a saved E2 Pantry Code.')],[P('Potable Water'),P('Aircraft_Potable_Water_Code_Definitions / E3 Potable Water.'),P('Optional. When supplied, must reference a saved E3 Potable Water Code.')],[P('Service Weight'),P('Aircraft_Service_Weight_Adjustment_Codes / E3 Service Weight Adjustment Codes.'),P('Optional. This is the single primary Service Weight item for the configuration.')]]
story += [table(primary,[175,310,300]),Spacer(1,12),P('Additional Service Weight Adjustment items','H2X')]
additional=[[P('COLUMN','Head'),P('RULE','Head')],[P('Weight Configuration Code'),P('Required; must reference an existing primary Weight Configuration Code.')],[P('Service Weight Adjustment'),P('Required; must reference an E3 Service Weight Adjustment Code. It cannot duplicate the primary Service Weight item or another additional item for that configuration.')],[P('Storage'),P('Stored as one row per configuration and adjustment in Aircraft_Weight_Configuration_Service_Adjustments, allowing any number of additional items.')]]
story += [table(additional,[230,555]),Spacer(1,12),P('Display and interaction standards','H2X')]
display=[[P('STANDARD','Head'),P('APPLICATION','Head')],[P('Layout, controls and alignment'),P('Use proportioned columns with no horizontal scrolling at the standard desktop width. Edit controls are 46 px high. Text aligns consistently; any numeric headings are centred and numeric values are right aligned.')],[P('Presentation, status and saving'),P('Use no thousands separators; Index is one decimal place and Index Per Weight Unit is five decimal places. Apply the global colour palette and keep the page badge at the far right. SAVE validates atomically; CANCEL discards unsaved changes. Removing a primary configuration also removes its additional items.')]]
story += [table(display,[230,555])]
doc.build(story,onFirstPage=footer,onLaterPages=footer);print(out)
